#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/pstree/tasks/func-myps.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="List processes for the current user, optionally filtered"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

# USAGE arg "[process]" default="" help="Filter processes by name or PID"

import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def exit_code(rc):
  """The exit code of the shell for a return code of subprocess."""
  return 128 - rc if rc < 0 else rc


def user_env():
  """The environment of the user for the tool: without VIRTUAL_ENV and
  without the bin folder of the script environment on PATH, which uv run
  adds."""
  env = dict(os.environ)
  env.pop("VIRTUAL_ENV", None)
  script_bin = os.path.normpath(os.path.join(sys.prefix, "bin"))
  path = env.get("PATH", "").split(os.pathsep)
  env["PATH"] = os.pathsep.join(p for p in path if os.path.normpath(p) != script_bin)
  return env


def ancestry():
  """Our own ancestry (this script, uv, mise, the shell...) so it never
  matches itself."""
  pids = set()
  pid = os.getpid()
  while pid > 1:
    pids.add(pid)
    proc = subprocess.run(["ps", "-o", "ppid=", "-p", str(pid)], check=False, stdout=subprocess.PIPE, text=True)
    if proc.returncode:
      sys.exit(exit_code(proc.returncode))
    text = proc.stdout.replace(" ", "").strip("\n")
    pid = int(text) if text.isdigit() else 0
  return pids


def main():
  user = os.environ["USER"]
  filter_ = os.environ.get("usage_process", "")
  args = ["-g", "2", "-l", "7"]

  if not filter_:
    helpers.print_header(f"Listing processes for user {user} ...")
    # The process of pstree replaces this process.
    sys.stdout.flush()
    os.execvpe("pstree", ["pstree", *args, "-u", user], user_env())

  helpers.print_header(f"Listing processes for user {user} filtered by {filter_} ...")

  self_pids = ancestry()

  pids = []
  if re.fullmatch(r"[0-9]+", filter_):
    found = subprocess.run(
      ["ps", "-p", filter_], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
    ).returncode
    if found == 0:
      pids.append(filter_)
  else:
    # pgrep matches the process name (not argv) and never reports itself
    out = subprocess.run(["pgrep", "-U", user, "--", filter_], check=False, stdout=subprocess.PIPE, text=True).stdout
    for p in out.splitlines():
      p = p.strip()
      if p and not (p.isdigit() and int(p) in self_pids):
        pids.append(p)

  if not pids:
    print(f"No processes found matching '{filter_}'", flush=True)
    sys.exit(1)

  for p in pids:
    args += ["-p", p]

  sys.stdout.flush()
  rc = subprocess.run(["pstree", *args], check=False, env=user_env()).returncode
  sys.exit(exit_code(rc))


if __name__ == "__main__":
  main()
